            self.buf[self.idx] = b;
            self.idx += 1;
        }
    }

    pub fn writeSlice(self: *BufferWriter, s: []const u8) void {
        for (s) |b| {
            self.writeByte(b);
        }
    }

    pub fn getWritten(self: *const BufferWriter) []const u8 {
        return self.buf[0..self.idx];
    }
};

